package com.agriconnect.analytics;
import jakarta.servlet.http.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.client.*;
/** Temporary compatibility adapter only for forecast/AI APIs not yet represented by event read models. */
@RestController class AnalyticsProxyController{private final RestClient core;AnalyticsProxyController(RestClient c){core=c;}private ResponseEntity<byte[]>get(String path,HttpServletRequest q){try{return core.get().uri(path+(q.getQueryString()==null?"":"?"+q.getQueryString())).header("Authorization",q.getHeader("Authorization")).header("X-Internal-Api-Key",System.getenv().getOrDefault("INTERNAL_API_KEY","local-dev-key")).retrieve().toEntity(byte[].class);}catch(ResourceAccessException e){throw new ServiceUnavailable("Core analytics compatibility adapter timed out");}}@GetMapping("/api/analytics/production-forecast")ResponseEntity<byte[]>production(HttpServletRequest q){return get("/api/forecasts",q);}@GetMapping("/api/analytics/demand-forecast")ResponseEntity<byte[]>demand(HttpServletRequest q){return get("/api/analytics/forecast-inventory",q);}@GetMapping({"/api/analytics/overview","/api/analytics/province-stats","/api/analytics/rescue-rates","/api/analytics/supply-capacity","/api/analytics/congestion-risk","/api/analytics/forecast-inventory"})ResponseEntity<byte[]>legacyAnalytics(HttpServletRequest q){return get(q.getRequestURI(),q);}@GetMapping({"/api/inventory-risk-forecast/**","/api/forecasts/**","/api/forecast-results/**","/api/forecast-dataset/**","/api/ai/**"})ResponseEntity<byte[]>proxy(HttpServletRequest q){return get(q.getRequestURI(),q);}static class ServiceUnavailable extends RuntimeException{ServiceUnavailable(String m){super(m);}}}
